package tw.com.tft.documentscanner.imaging;import android.graphics.*;import androidx.exifinterface.media.ExifInterface;import org.opencv.android.Utils;import org.opencv.core.*;import org.opencv.imgcodecs.Imgcodecs;import org.opencv.imgproc.Imgproc;import java.io.*;import tw.com.tft.documentscanner.model.FilterMode;public final class ImageProcessor{public static Bitmap processPreview(Bitmap b,float[]c,FilterMode m){Mat r=new Mat();Utils.bitmapToMat(b,r);Mat x=new Mat();Imgproc.cvtColor(r,x,Imgproc.COLOR_RGBA2BGR);r.release();Mat w=warp(x,c,2600);x.release();Mat e=ImageEnhancer.apply(w,m);w.release();Mat o=new Mat();Imgproc.cvtColor(e,o,Imgproc.COLOR_BGR2RGBA);Bitmap z=Bitmap.createBitmap(o.cols(),o.rows(),Bitmap.Config.ARGB_8888);Utils.matToBitmap(o,z);e.release();o.release();return z;}public static File processFull(String p,float[]c,FilterMode m,File out,int max)throws Exception{Mat s=Imgcodecs.imread(p,Imgcodecs.IMREAD_COLOR);if(s.empty())throw new IllegalArgumentException("read");s=exif(s,p);int l=Math.max(s.cols(),s.rows());if(l>max){double z=max/(double)l;Mat q=new Mat();Imgproc.resize(s,q,new Size(),z,z,Imgproc.INTER_AREA);s.release();s=q;}Mat w=warp(s,c,max);s.release();Mat e=ImageEnhancer.apply(w,m);w.release();File par=out.getParentFile();if(par!=null&&!par.exists())par.mkdirs();MatOfInt ps=new MatOfInt(Imgcodecs.IMWRITE_JPEG_QUALITY,98);boolean ok=Imgcodecs.imwrite(out.getAbsolutePath(),e,ps);ps.release();e.release();if(!ok)throw new IllegalStateException("jpeg");return out;}private static Mat warp(Mat s,float[]c,int max){float[]p=c!=null&&c.length==8?c:DocumentDetector.safeInset();Point tl=new Point(p[0]*s.cols(),p[1]*s.rows()),tr=new Point(p[2]*s.cols(),p[3]*s.rows()),br=new Point(p[4]*s.cols(),p[5]*s.rows()),bl=new Point(p[6]*s.cols(),p[7]*s.rows());int w=Math.max(64,(int)Math.round(Math.max(d(br,bl),d(tr,tl)))),h=Math.max(64,(int)Math.round(Math.max(d(tr,br),d(tl,bl))));int l=Math.max(w,h);if(l>max){double z=max/(double)l;w=(int)(w*z);h=(int)(h*z);}MatOfPoint2f a=new MatOfPoint2f(tl,tr,br,bl),b=new MatOfPoint2f(new Point(0,0),new Point(w-1,0),new Point(w-1,h-1),new Point(0,h-1));Mat t=Imgproc.getPerspectiveTransform(a,b);Mat o=new Mat();Imgproc.warpPerspective(s,o,t,new Size(w,h),Imgproc.INTER_CUBIC,Core.BORDER_REPLICATE);a.release();b.release();t.release();return o;}private static Mat exif(Mat s,String p){try{int o=new ExifInterface(new File(p)).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);Mat q=new Mat();if(o==ExifInterface.ORIENTATION_ROTATE_90)Core.rotate(s,q,Core.ROTATE_90_CLOCKWISE);else if(o==ExifInterface.ORIENTATION_ROTATE_180)Core.rotate(s,q,Core.ROTATE_180);else if(o==ExifInterface.ORIENTATION_ROTATE_270)Core.rotate(s,q,Core.ROTATE_90_COUNTERCLOCKWISE);else return s;s.release();return q;}catch(Exception e){return s;}}private static double d(Point a,Point b){return Math.hypot(a.x-b.x,a.y-b.y);}}